  ["Route there on anything: road, flight, boat."] = "Una ruta hacia cualquier cosa: camino, vuelo, barco.",
  ["Show the welcome at every login"] = "Mostrar la bienvenida en cada inicio de sesión",
  ["Sit by a fire together, share it with your group, a camp ring for the evening."] = "Sentarse juntos junto a una hoguera, compartirla con tu grupo, un anillo de campamento para la noche.", -- luacheck: ignore 631
  ["Switch on %s on the Suite page."] = "Activa %s en la página Suite.",
  ["Talk to a quest giver with the conversation on"] = "Hablar con quien da una misión con la conversación activada", -- luacheck: ignore 631
  ["Talk to people without quest windows"] = "Hablar con la gente sin ventanas de misión",
  ["Text"] = "Texto",
  ["The Gestures ring"] = "El anillo de Gestos",
  ["The Orbiter"] = "El Orbiter",
  ["The Orbiter plays Spoken's voices for quests, places, books and bosses, and the game's voice where Spoken has none."] = "El Orbiter reproduce las voces de Spoken para misiones, lugares, libros y jefes, y la voz del juego donde Spoken no tiene.", -- luacheck: ignore 631
  ["The Orbiter plays the zone's story."] = "El Orbiter reproduce la historia de la zona.",
  ["The campfire"] = "La hoguera",
  ["The hub: every app's settings, the Suite page, Help."] = "El centro: los ajustes de cada aplicación, la página Suite, la ayuda.", -- luacheck: ignore 631
  ["The land speaks"] = "La tierra habla",
  ["The land tells its stories as you walk (the Orbiter with Spoken)"] = "La tierra cuenta sus historias mientras caminas (el Orbiter con Spoken)", -- luacheck: ignore 631
  ["The screen for the view"] = "La pantalla para la vista",
  ["The search opens a page for anything."] = "La búsqueda abre una página para cualquier cosa.",
  ["The suite's button at the minimap"] = "El botón de la suite en el minimapa",
  ["The suite's words"] = "Las palabras de la suite",
  ["The way there, by road, flight and boat"] = "El camino, por carretera, vuelo y barco",
  ["The welcome stays away at login; the General page brings it back."] = "La bienvenida ya no aparece al iniciar sesión; la página General la recupera.", -- luacheck: ignore 631
  ["The welcome window at every login, until Don't show again in its corner (plan-launch-version D)."] = "La ventana de bienvenida en cada inicio de sesión, hasta No volver a mostrar en su esquina (plan-launch-version D).", -- luacheck: ignore 631
  ["Try it"] = "Probar",
  ["What matters for this way"] = "Lo que importa en este camino",
  ["What you get"] = "Lo que obtienes",
  ["Where things are"] = "Dónde están las cosas",
  ["You know the way."] = "Ya conoces el camino.",
  ["Your first five minutes"] = "Tus primeros cinco minutos",
  ["Your gestures on a ring, thanks in your own words"] = "Tus gestos en un anillo, gracias con tus propias palabras", -- luacheck: ignore 631
  ["Your pack"] = "Tu equipaje",
  -- the welcome's information layer (02.11.2026)
  ["Highpeak"] = "Pico Alto",
  ["Greenback Ridge"] = "Cresta Lomoverde",
  ["Peacebloom"] = "Flor de paz",
  ["%d yd high, %d yd away"] = "%d m de alto, a %d m",
  ["%d yd away"] = "a %d m",
  -- the artist's credit under a hand-drawn dungeon map (ADR 0048, 02.11.2026)
  ["Map by %s"] = "Mapa de %s",
  ["Map by %s (%s), used with kind permission. Thank you!"] = "Mapa de %s (%s), usado con su amable permiso. ¡Gracias!",
  ["Click, then Ctrl+C to copy the address"] = "Haz clic y luego Ctrl+C para copiar la dirección",
  -- the minimap buttons
  ["Welcome"] = "Bienvenida",
  ["Its own minimap button for the welcome"] = "Su propio botón en el minimapa para la bienvenida",
  ["A button at the minimap that shows the welcome with the Wanderer and the Scholar again."] = "Un botón en el minimapa que vuelve a mostrar la bienvenida con el Errante y el Erudito.",
  ["%s is switched off. Its page has the switch to turn it on."] = "%s está desactivado. Su página tiene el interruptor para activarlo.",
  ["Click: its page, to switch it on."] = "Clic: su página, para activarlo.",

  -- What's new (ADR 0021, LG5): the release notes, keyed by their English text
  ["Bastian's minimap shows the herbs, ore and creatures your tracking finds on its own styles too, and the game's tracking button is back in its tools row."] = "El minimapa de Bastian muestra también, en sus propios estilos, las hierbas, minerales y criaturas que encuentra tu rastreo, y el botón de rastreo del juego vuelve a su barra de herramientas.",
  ["The session plan (what fits into the next 30 to 180 minutes) moved from Route's Explore to Bastian's Gold and is off until you switch it on in Gold's settings."] = "El plan de sesión (lo que cabe en los próximos 30 a 180 minutos) pasó de Explorar de Route a Bastian's Gold y queda apagado hasta que lo actives en los ajustes de Gold.",
  ["Other addons can ask Bastian's for any thing's name and places, your notes near a spot and your gold income through Bastians.API."] = "Otros addons pueden preguntar a Bastian's, a través de Bastians.API, el nombre y los lugares de cualquier cosa, tus notas cerca de un punto y tus ingresos de oro.",
  ["When Bastian's Helpers restocks an item, it tells you if another vendor sells it cheaper and where."] = "Cuando Bastian's Helpers repone un objeto, te dice si otro vendedor lo vende más barato y dónde.",
  ["What's new speaks your language: German, French, Spanish, Korean and Chinese."] = "Novedades habla tu idioma: alemán, francés, español, coreano y chino.",
  ["An item's price page shows a small chart of the prices your own auction house scans saw over the last two weeks."] = "La página de precio de un objeto muestra una pequeña gráfica de los precios que vieron tus propios escaneos de la casa de subastas en las últimas dos semanas.",
  ["Mail rules: tell Helpers which character gets your herbs, ore, cloth and more, and one click beside the send tab fills the mail."] = "Reglas de correo: dile a Helpers qué personaje recibe tus hierbas, menas, telas y más; un clic junto a la pestaña de envío rellena el correo.",
  ["Campfire can share your fire on a public channel and show everyone's fires (off by default, with a block list)."] = "Campfire puede compartir tu fogata en un canal público y mostrar las fogatas de todos (desactivado por defecto, con una lista de bloqueo).",
  ["Bastian's Suite now speaks Russian and Brazilian Portuguese."] = "Bastian's Suite ahora habla ruso y portugués de Brasil.",
  ["A Gestures command can now cast, use and target: /cast and friends run as a macro when you click the wedge."] = "Un comando de Gestures ahora puede lanzar, usar y fijar objetivo: /cast y compañía se ejecutan como macro al hacer clic en la cuña.",
  ["Other addons can now read and set Bastian's waypoint, read the account's gold and the suite's item sets through Bastians.API."] = "Otros addons ahora pueden leer y fijar el punto de ruta de Bastian's, leer el oro de la cuenta y los conjuntos de objetos de la suite a través de Bastians.API.",
  ["Spoken 3.8.0, the launch client's copy, is now the version the suite was tested with; the hub no longer flags it as newer."] = "Spoken 3.8.0, la versión del cliente de lanzamiento, cuenta ahora como probada; el centro ya no la marca como más nueva.",
  ["The game's voice that reads quest texts is a woman's by default and can be chosen in the Orbiter's settings."] = "La voz del juego que lee los textos de misión es por defecto una voz de mujer y se puede elegir en los ajustes del Orbiter.",
  ["Without Spoken, the Orbiter reads a quest's text with the game's own voice (Accessibility settings)."] = "Sin Spoken, el Orbiter lee el texto de una misión con la voz del juego (ajustes de accesibilidad).",
  ["Bastian's Orbiter (the Voice addon, renamed): the panel keeps its place and grows around its middle, says what it plays and what a click did, has pictogram controls and its own minimap button; the game's settings pages of the suite scroll."] = "Bastian's Orbiter (el addon Voice, renombrado): el panel conserva su sitio y crece alrededor de su centro, dice qué reproduce y qué hizo un clic, tiene controles con pictogramas y su propio botón de minimapa; las páginas de ajustes de la suite en el juego se desplazan.",
  ["Bastian's Voice: Play on quests, zones, areas, bosses and books where Spoken has a line, the Lore Orbit around you, and quest conversations without the game's windows (off by default)."] = "Bastian's Voice: reproducción en misiones, zonas, áreas, jefes y libros donde Spoken tiene una línea, la Órbita de historias a tu alrededor y conversaciones de misión sin las ventanas del juego (desactivado por defecto).",
  ["A note you add on a dungeon's page (or any other page) now shows on that page."] = "Una nota que añades en la página de una mazmorra (o de cualquier otra página) ahora se muestra en esa página.",
  ["The minimap's search finds only NPCs, quests, zones, your notes and bookmarks, and marks the place it jumps to; a quest marks its quest giver."] = "La búsqueda del minimapa solo encuentra PNJ, misiones, zonas, tus notas y marcadores, y marca el lugar al que salta; una misión marca a quien la da.",
  ['"Show on map" now draws what you chose (its icon and name at every place) and selects it, even when its layer is off.'] = '"Mostrar en el mapa" ahora dibuja lo que elegiste (su icono y su nombre en cada lugar) y lo selecciona, aunque su capa esté desactivada.',
  ["The map has a Dungeons and raids layer, and it switches on by itself when you pick a dungeon in the Browser."] = 'El mapa tiene una capa "Calabozos y bandas" que se activa sola cuando eliges una mazmorra en el Browser.',
  ["New app Bastian's Helpers: sells junk, repairs, restocks, takes all mail, helps at quest givers and shows IDs on tooltips."] = "Nueva aplicación Bastian's Helpers: vende chatarra, repara, repone existencias, recoge todo el correo, ayuda con quienes dan misiones y muestra los ID en las descripciones emergentes.",
  ["The dungeon pages name the right bosses; some showed an unrelated creature (Shadowfang Keep's first boss as Archaedas) with loot that was not its own."] = "Las páginas de mazmorra nombran a los jefes correctos; algunas mostraban una criatura sin relación (el primer jefe del Castillo de Colmillo Oscuro como Archaedas) con botín que no era suyo.",
  ["Minimap buttons close what they opened; Gestures' button opens its options; a switched-off app's button leads to its switch; a new button shows the welcome again."] = "Los botones del minimapa cierran lo que abrieron; el botón de Gestos abre sus opciones; el botón de una aplicación desactivada lleva a su interruptor; un botón nuevo vuelve a mostrar la bienvenida.",
  ["Forever's own dungeons (Dalaran, the Wetlands excavation, the Hall of Thanes, the Ruins of Lordaeron) now show Santiago Reyes' hand-drawn maps with the bosses marked - thank you, Santiago!"] = "Las mazmorras propias de Forever (Dalaran, la excavación de los Humedales, el Salón de los Thanes, las Ruinas de Lordaeron) ahora muestran los mapas dibujados a mano por Santiago Reyes con los jefes marcados - ¡gracias, Santiago!",
  ["German, French and Spanish players read most quests' whole texts in their language, and the AddOn list speaks every language of the suite."] = "Los jugadores alemanes, franceses y españoles leen los textos completos de la mayoría de las misiones en su idioma, y la lista de AddOns habla todos los idiomas de la suite.",
  ["The game's AddOn list shows the suite as one folding \"Bastian's Suite\" header with the data packs and map styles folded under their app, in Korean and Chinese too."] = 'La lista de AddOns del juego muestra la suite como un único encabezado plegable "Bastian\'s Suite", con los paquetes de datos y los estilos de mapa plegados bajo su aplicación, también en coreano y chino.',
  ["Korean and Chinese players read the quests' whole texts in their language, and Bastian's Chat speaks French, Spanish, Korean and Chinese."] = "Los jugadores coreanos y chinos leen los textos completos de las misiones en su idioma, y Bastian's Chat habla francés, español, coreano y chino.",
  ["With Total RP 3 or MyRolePlay, Chat, Gestures and the Orbiter show other players' roleplay names."] = "Con Total RP 3 o MyRolePlay, Chat, Gestures y el Orbiter muestran los nombres de rol de otros jugadores.",
  ["A new welcome: choose the Wanderer or the Scholar with a picture of your own race, set up your pack, and try your first five minutes step by step."] = "Una nueva bienvenida: elige al Caminante o al Erudito con una imagen de tu propia raza, configura tu paquete y prueba tus primeros cinco minutos paso a paso.",
  ["Bastian's Campfire: a card while a fire is near, a camp ring in Gestures, share the fire with your group and guild, and a planner of every camp feature."] = "Bastian's Campfire: una tarjeta cuando hay una hoguera cerca, un anillo de campamento en Gestos, compartir la hoguera con tu grupo y tu hermandad, y un planificador de todas las funciones del campamento.",
  ["Emotes in Bastian's Chat now show in the colour scheme's own emote colour, for roleplay."] = "Los emotes en Bastian's Chat se muestran ahora con el color de emote propio de la combinación de colores, para el rol.",
  ["A Gestures wedge can run one of your own macros with a click, and runs the game's own commands such as /reload; Quests' item buttons work with \"cast on key down\"."] = 'Un sector de Gestos puede ejecutar una de tus macros con un clic y ejecuta los comandos del juego como /reload; los botones de objeto de Quests funcionan con "lanzar al pulsar la tecla".',
  ["The Korean and Chinese texts of the suite read naturally and use the game's own terms."] = "Los textos en coreano y chino de la suite se leen con naturalidad y usan los términos propios del juego.",
  ["Build your Gestures rings as you like: name them, pick any emote, your own lines, commands, the suite's and the game's controls through one filter; the wheel turns the right way; a conversation's choices no longer overlap on the Orbiter."] = "Crea tus anillos de Gestos a tu gusto: ponles nombre, elige cualquier emote, tus propias líneas, comandos y los controles de la suite y del juego mediante un único filtro; la rueda gira en el sentido correcto; las opciones de una conversación ya no se solapan en el Orbiter.",
  ["When someone challenges, trades or invites you, Gestures offers a bow, a wave or a polite decline; Chat's + menu has a Roleplay tab."] = "Cuando alguien te desafía, comercia contigo o te invita, Gestos ofrece una reverencia, un saludo o una negativa educada; el menú + del Chat tiene una pestaña de Rol.",
  ["Gestures' Route home, Mark heard and Toggle the tracker wedges light up."] = 'Los sectores "Ruta a casa", "Marcar como escuchado" y "Mostrar u ocultar el rastreador" de Gestos ahora se iluminan.',
  ["The Orbiter says when your Spoken is newer or older than the suite was tested with, never talks over Spoken or Spoken Players, and Bastian's Helpers, Chat and the Orbiter show up on broker displays; other addons can ask who knows a recipe, let the Orbiter speak, read your play preset and open any app."] = "El Orbiter avisa cuando tu Spoken es más nuevo o más antiguo que la versión con la que se probó la suite, nunca habla por encima de Spoken o Spoken Players, y Bastian's Helpers, Chat y el Orbiter aparecen en las pantallas de broker; otros addons pueden preguntar quién conoce una receta, hacer hablar al Orbiter, leer tu perfil de juego y abrir cualquier aplicación.",
  ["Every app wears its own mark on the minimap, in the hub, on broker displays and in the AddOns list: a compass star for the suite, a scroll for Quests, a pin for the Map, a lens for the Browser, a balance for Gold, a signpost for Route, a quill for Notes, two characters for Alts, a wrench for Helpers, bubbles for Chat, a hand for Gestures."] = "Cada aplicación lleva su propia marca en el minimapa, en el hub, en las pantallas de broker y en la lista de AddOns: una estrella de brújula para la suite, un pergamino para Quests, una marca para el mapa, una lupa para el Browser, una balanza para Gold, un poste indicador para Route, una pluma para Notes, dos personajes para Alts, una llave inglesa para Helpers, burbujas para Chat, una mano para Gestures.",
  ["Choose how you play at the first start: the Wanderer hears Azeroth with nearly no UI, the Scholar has every quest, creature, item and place one click away; Bastian's Gestures brings emote rings and courtesy; the hub explains every app and key."] = "Elige al empezar cómo juegas: el Caminante oye Azeroth casi sin interfaz, el Erudito tiene cada misión, criatura, objeto y lugar a un clic; Bastian's Gestures trae anillos de emotes y cortesía; el hub explica cada aplicación y cada tecla.",
  ["Every button shows its pictogram again and the words sit where they belong; chat tabs and buttons are easy to tell apart; the Orbiter's controls click with a creature shown, its hub drags it, and its answers are symbols; an item's page says which of your characters has it."] = "Cada botón vuelve a mostrar su pictograma y las palabras están donde deben; las pestañas de chat y los botones se distinguen con facilidad; los controles del Orbiter responden al clic cuando se muestra una criatura, su hub lo arrastra y sus respuestas son símbolos; la página de un objeto indica cuál de tus personajes lo tiene.",
  ["Trainers say what they train on the map and on their page, and their list of spells shows who of your characters knows each one; item lists filter by who owns an item; the Orbiter hides with the clear-screen key and drags by its hub; the Browser's hover preview is a setting."] = "Los instructores indican en el mapa y en su página qué enseñan, y su lista de hechizos muestra cuál de tus personajes conoce cada uno; las listas de objetos se filtran por quién posee un objeto; el Orbiter se oculta con la tecla de despejar la pantalla y se arrastra por su hub; la vista previa al pasar el ratón del Browser es un ajuste.",
  ["Every app offers a data-broker feed (Titan, Bazooka, ElvUI and the like), the Addon Compartment lists the suite, bag addons get the suite's item sets, and other addons can read the suite through Bastians.API."] = "Cada aplicación ofrece una fuente de data broker (Titan, Bazooka, ElvUI y similares), el compartimento de addons muestra la suite, los addons de bolsas reciben los conjuntos de objetos de la suite y otros addons pueden leer la suite mediante Bastians.API.",
  ["The Orbiter's bubbles glide to their places and the one that plays is coloured; Show on map always draws what you chose; the junk filter also cleans the lines already on screen; the game's voice is found once the client lists it."] = 'Las burbujas del Orbiter se deslizan a su sitio y la que suena aparece coloreada; "Mostrar en el mapa" siempre dibuja lo que elegiste; el filtro de chatarra también limpia las líneas que ya están en pantalla; la voz del juego se encuentra en cuanto el cliente la lista.',
  ["Seven looks to pick from, including Night, Glass and Parchment; every button of the suite shows a pictogram; every colour scheme is checked for readable text."] = "Siete aspectos entre los que elegir, entre ellos Noche, Cristal y Pergamino; cada botón de la suite muestra un pictograma; cada combinación de colores se ha comprobado para que el texto sea legible.",
  ["the Browser's filter pills use the pane's width and the first row is never hidden, the Mobs search works again, zones appear once, a preview needs Shift, and a note saved on a page shows at once."] = "Las etiquetas de filtro del Browser usan el ancho del panel y la primera fila nunca queda oculta, la búsqueda de monstruos vuelve a funcionar, las zonas aparecen una sola vez, una vista previa requiere Shift y una nota guardada en una página se muestra al instante.",
  ['one search syntax in every box (words, "phrases", OR, -not, field:value, level>30), the text keys Ctrl+Backspace/Delete/Left/Right, a key that clears the screen for role play, a lock on every window, and the new look engine behind Modern and WoW.'] = 'Una única sintaxis de búsqueda en cada cuadro (palabras, "frases", OR, -not, field:value, level>30), las teclas de texto Ctrl+Backspace/Delete/Left/Right, una tecla que despeja la pantalla para el rol, un candado en cada ventana y el nuevo motor de aspecto detrás de Moderno y WoW.',
  ['Bastian\'s Helpers also writes its notices into a chat tab named "Addons" when you have one.'] = 'Bastian\'s Helpers también escribe sus avisos en una pestaña de chat llamada "Addons" si tienes una.',
  ['The colour picker opens in front of the settings, and no "blocked" message appears in combat.'] = 'El selector de color se abre delante de los ajustes y ya no aparece ningún mensaje de "bloqueado" en combate.',
  ["The map's layer bar names each icon the moment you point at it."] = "La barra de capas del mapa nombra cada icono en cuanto lo señalas.",
  ["Other addons can ask Bastian's for prices, quest state, the active route and travel times, start a route, and listen to its events through Bastians.API."] = "Otros addons pueden pedirle a Bastian's precios, el estado de las misiones, la ruta activa y los tiempos de viaje, iniciar una ruta y escuchar sus eventos mediante Bastians.API.",
  ["Wide buttons in the WoW look keep the game's rounded ends instead of stretching them."] = "Los botones anchos con el aspecto de WoW conservan los extremos redondeados del juego en lugar de estirarlos.",
  ["Bastian's apps show in Titan Panel, Bazooka, EllesmereUI's data bars and every other LibDataBroker display, in the addon compartment, and sort your bags in BetterBags, Baganator and AdiBags."] = "Las aplicaciones de Bastian's aparecen en Titan Panel, Bazooka, las barras de datos de EllesmereUI y cualquier otra pantalla de LibDataBroker, en el compartimento de addons, y ordenan tus bolsas en BetterBags, Baganator y AdiBags.",
  ["Bastian's Chat gets a live tab filter, tab windows that dock back, a Messenger of the WhatsApp kind with class icons and a search, and a lock on every chat window."] = "Bastian's Chat recibe un filtro de pestañas en vivo, ventanas de pestaña que vuelven a acoplarse, un Messenger al estilo de WhatsApp con iconos de clase y una búsqueda, y un candado en cada ventana de chat.",
}
ns.L:Register("esES", strings)
ns.L:Register("esMX", strings)
